#include <stdio.h>
#include <string.h>

int main()
{
    char a[60], b[60], buf[100];
    int lines = 0, len;
    FILE *fp;
    scanf("%s %s", a, b);
    fp = fopen("f108.txt", "w");
    fprintf(fp, "%s\n%s\n", a, b);
    fclose(fp);
    fp = fopen("f108.txt", "r");
    while (fgets(buf, sizeof(buf), fp) != NULL)
    {
        len = strlen(buf);
        if (len > 0 && buf[len - 1] == '\n')
            buf[len - 1] = '\0';
        if (buf[0] == '\0')
            continue;
        printf("%s\n", buf);
        lines++;
    }
    fclose(fp);
    printf("%d\n", lines);
    remove("f108.txt");
    return 0;
}

