#include <stdio.h>

int main()
{
    FILE *fp;
    int ch;
    int letters = 0, digits = 0, others = 0;
    char s[300];
    scanf("%s", s);
    fp = fopen("f111.txt", "w");
    fprintf(fp, "%s", s);
    fclose(fp);
    fp = fopen("f111.txt", "r");
    while ((ch = fgetc(fp)) != EOF)
    {
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'))
            letters++;
        else if (ch >= '0' && ch <= '9')
            digits++;
        else
            others++;
    }
    fclose(fp);
    remove("f111.txt");
    printf("%d %d %d\n", letters, digits, others);
    return 0;
}

